133	import org.springframework.jdbc.core.RowMapper;
134	import org.springframework.jdbc.support.GeneratedKeyHolder;
135	import org.springframework.stereotype.Repository;
136	
137	/** Claims by sheet, newest first. */
138	@Repository
139	public class ClaimRepository {
140	
141	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getString("sheet_id"),
142	            rs.getLong("person_id"), rs.getBigDecimal("amount"), rs.getObject("claim_date", LocalDate.class),
143	            rs.getString("note"), ClaimStatus.valueOf(rs.getString("status")),
144	            rs.getObject("claim_number", Integer.class), rs.getBigDecimal("settled_due"),
145	            rs.getString("opened_by"), rs.getBoolean("stated"), rs.getBigDecimal("stated_due"));
146	
147	    private final JdbcTemplate jdbc;
148	
149	    public ClaimRepository(JdbcTemplate jdbc) {
150	        this.jdbc = jdbc;
151	    }
152	
153	    public List<Claim> list(String sheetId) {
154	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? ORDER BY id DESC", ROW, sheetId);
155	    }
156	
157	    /** The claim on this sheet, or null when absent. */
158	    public Claim find(String sheetId, long id) {
159	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND id = ?", ROW, sheetId, id)
160	                .stream().findFirst().orElse(null);
161	    }
162	
163	    public Claim insert(Claim claim) {
164	        var keys = new GeneratedKeyHolder();
165	        jdbc.update(con -> {
166	            var ps = con.prepareStatement(
167	                    "INSERT INTO claim (sheet_id, person_id, amount, claim_date, note) VALUES (?, ?, ?, ?, ?)",
168	                    new String[] { "id" });
169	            ps.setString(1, claim.sheetId());
170	            ps.setLong(2, claim.personId());
171	            ps.setBigDecimal(3, claim.amount());
172	            ps.setObject(4, claim.date());
173	            ps.setString(5, claim.note());
174	            return ps;
175	        }, keys);
176	        return new Claim(keys.getKey().longValue(), claim.sheetId(), claim.personId(), claim.amount(),
177	                claim.date(), claim.note(), ClaimStatus.DRAFT, null, null, null, false, null);
178	    }
179	
180	    /** The person's claims, newest first. */
181	    public List<Claim> listForPerson(String sheetId, long personId) {
182	        return jdbc.query("SELECT * FROM claim WHERE sheet_id = ? AND person_id = ? ORDER BY id DESC", ROW, sheetId,
183	                personId);
184	    }
185	
186	    /** Bind the claim to a statement's figure (null: n/a, its due stays live), or unbind it (stated false). */
187	    public void state(Claim claim, boolean stated, BigDecimal statedDue) {
188	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet_id = ? AND id = ?",
189	                stated, statedDue, claim.sheetId(), claim.id());
190	    }
191	
192	    public void update(Claim claim) {
193	        jdbc.update("UPDATE claim SET amount = ?, claim_date = ?, note = ? WHERE sheet_id = ? AND id = ?",
194	                claim.amount(), claim.date(), claim.note(), claim.sheetId(), claim.id());
195	    }
196	
197	    /** Move the claim from one status to another, with its settled due and who opened it: false when it no longer has
198	     *  the status it was loaded with (another user changed it first), and nothing is written. */
199	    public boolean changeStatus(Claim claim, ClaimStatus to, Integer number, BigDecimal settledDue,
200	            String openedBy) {
201	        return jdbc.update(
202	                "UPDATE claim SET status = ?, claim_number = ?, settled_due = ?, opened_by = ? WHERE sheet_id = ? AND id = ? AND status = ?",
203	                to.name(), number, settledDue, openedBy, claim.sheetId(), claim.id(), claim.status().name()) == 1;
204	    }
205	
206	    /** Take the next claim number on the sheet. The update locks the sheet's row until the transaction
207	     *  ends, so concurrent openings are numbered one after the other; a rolled-back one gives its number
208	     *  back, so there are no gaps. */
209	    public int nextNumber(String sheetId) {
210	        jdbc.update("UPDATE sheet SET last_claim_number = last_claim_number + 1 WHERE id = ?", sheetId);
211	        return jdbc.queryForObject("SELECT last_claim_number FROM sheet WHERE id = ?", Integer.class, sheetId);
212	    }
213	}
