242	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; a DRAFT or OPEN claim may be VOID.
243	 *  Only OPEN and SETTLED claims count toward the totals. */
244	public enum ClaimStatus {
245	    DRAFT, OPEN, SETTLED, VOID;
246	
247	    /** Whether a claim with this status counts toward the totals (and is bound by a statement). */
248	    public boolean counts() {
249	        return this == OPEN || this == SETTLED;
250	    }
251	
252	    /** Whether a claim with this status may move to the given one. */
253	    public boolean canBecome(ClaimStatus to) {
254	        return switch (to) {
255	            case OPEN -> this == DRAFT;
256	            case SETTLED -> this == OPEN;
257	            case VOID -> this == DRAFT || this == OPEN;
258	            case DRAFT -> false;
259	        };
260	    }
261	}
