456	/** Move the loaded claim to its new status, refusing a change its status does not allow (or one
457	 *  another user's change got to first). Opening gives the claim the sheet's next number; voiding
458	 *  keeps it (a number is never reused). Opening records who opened it, and that user may not settle it. Settling fixes its due
459	 *  as its row shows it now: the bound figure, else live at the person's grade rate now in force on the claim's date,
460	 *  at least the sheet's floor, with the late charge as of today frozen in. A clerk (any user not made a steward) may settle
461	 *  only a claim whose due (as shown: bound by a statement, else live, plus any late charge) is at or below the sheet's clerk limit; a due
462	 *  of n/a, or no limit, is within it. */
463	public class SaveClaimStatus {
464	    public void save(@Val ClaimStatusInput input, @Val Claim loaded, ClaimRepository repository,
465	            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings,
466	            SheetRepository sheets,
467	            Out<ClaimResponse> saved)
468	            throws ClaimStatusNotAllowedException {
469	        if (!loaded.status().canBecome(input.to())) {
470	            throw new ClaimStatusNotAllowedException(loaded.status(), input.to());
471	        }
472	        if (input.to() == ClaimStatus.SETTLED && input.user().equals(loaded.openedBy())) {
473	            throw new ClaimStatusNotAllowedException("The user who opened a claim cannot settle it.");
474	        }
475	        if (input.to() == ClaimStatus.SETTLED && Role.CLERK.equals(roles.of(loaded.sheetId(), input.user()))) {
476	            BigDecimal limit = settings.clerkLimit(loaded.sheetId());
477	            BigDecimal due = dueNow(loaded, people, rates, settings, sheets);
478	            if (limit != null && due != null && due.compareTo(limit) > 0) {
479	                throw new ClaimStatusNotAllowedException("A clerk cannot settle a claim whose due (" + due.toPlainString()
480	                        + ") is above the clerk limit (" + limit.toPlainString() + ").");
481	            }
482	        }
483	        String openedBy = input.to() == ClaimStatus.OPEN ? input.user() : loaded.openedBy();
484	        Integer number = switch (input.to()) {
485	            case OPEN -> repository.nextNumber(loaded.sheetId());
486	            default -> loaded.number();
487	        };
488	        BigDecimal settledDue = input.to() == ClaimStatus.SETTLED ? dueNow(loaded, people, rates, settings, sheets) : null;
489	        if (!repository.changeStatus(loaded, input.to(), number, settledDue, openedBy)) {
490	            // the transaction rolls back, so a number taken above is not used up
491	            throw new ClaimStatusNotAllowedException(loaded.status(), input.to());
492	        }
493	        saved.set(ClaimResponse.from(new Claim(loaded.id(), loaded.sheetId(), loaded.personId(), loaded.amount(),
494	                loaded.date(), loaded.note(), input.to(), number, settledDue, openedBy, loaded.stated(),
495	                loaded.statedDue())));
496	    }
497	
498	    /** The claim's due now, as its row shows it: the figure a statement bound it to, else live (amount times its
499	     *  person's grade rate in force on the claim's date, divided by 100, rounded half to even to two decimals, at
500	     *  least the sheet's floor), with the late charge on it as of the sheet's today added on top; null when it has
501	     *  no figure. */
502	    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates,
503	            SettingRepository settings, SheetRepository sheets) {
504	        var person = people.find(claim.sheetId(), claim.personId());
505	        return Dues.shown(claim, person.grades(), rates, settings.floor(claim.sheetId()),
506	                LateCharge.of(claim.sheetId(), settings, sheets));
507	    }
508	}
