533	/** Bind the body and refuse it before anything is read or written: the amount is required, a
534	 *  number 0.00 or more with up to two decimals; the date, when given, is a real yyyy-mm-dd date. */
535	public class ValidateClaim {
536	    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
537	        if (request == null || request.user() == null || request.user().isBlank()) {
538	            throw new InvalidClaimException("Sign in before changing claims.");
539	        }
540	        String amount = request.amount() == null ? "" : request.amount().trim();
541	        if (amount.isEmpty()) {
542	            throw new InvalidClaimException("An amount is required.");
543	        }
544	        if (!amount.matches("\\d{1,12}(\\.\\d{1,2})?")) {
545	            throw new InvalidClaimException("The amount must be a number, 0.00 or more, with up to two decimals.");
546	        }
547	        String rawDate = request.date() == null ? "" : request.date().trim();
548	        LocalDate date = null;
549	        if (!rawDate.isEmpty()) {
550	            if (!rawDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
551	                throw new InvalidClaimException("The date must be a date (yyyy-mm-dd).");
552	            }
553	            try {
554	                date = LocalDate.parse(rawDate);
555	            } catch (DateTimeParseException e) {
556	                throw new InvalidClaimException("The date must be a real date (yyyy-mm-dd).");
557	            }
558	        }
559	        String note = request.note() == null ? "" : request.note().trim();
560	        if (note.length() > 1000) {
561	            throw new InvalidClaimException("A note is at most 1000 characters.");
562	        }
563	        body.set(new ClaimInput(request.user().trim(), new BigDecimal(amount).setScale(2), date, note));
564	    }
565	}
