588	package net.officefloor.hq.app.statement;
589	
590	import java.math.BigDecimal;
591	import java.math.RoundingMode;
592	import java.time.LocalDate;
593	import java.util.List;
594	import net.officefloor.hq.app.claim.Claim;
595	import net.officefloor.hq.app.claim.ClaimStatus;
596	import net.officefloor.hq.app.person.Grades;
597	import net.officefloor.hq.app.rate.RateRepository;
598	
599	/** Claim figures and due-totals, as the screen shows them. */
600	public final class Dues {
601	    private Dues() {
602	    }
603	
604	    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, else
605	     *  live: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded half to
606	     *  even to two decimals, and at least the sheet's floor; null (n/a) when no rate applies. */
607	    public static BigDecimal figure(Claim claim, Grades grades, RateRepository rates, BigDecimal floor) {
608	        if (claim.settledDue() != null) {
609	            return claim.settledDue();
610	        }
611	        if (claim.statedDue() != null) {
612	            return claim.statedDue();
613	        }
614	        return live(claim, grades, rates, floor);
615	    }
616	
617	    /** A claim's due as its row shows it: the due fixed when it was settled, else its figure (bound or live) with
618	     *  the late charge on it added on top; null (n/a) when it has no figure. */
619	    public static BigDecimal shown(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
620	            LateCharge late) {
621	        if (claim.settledDue() != null) {
622	            return claim.settledDue();
623	        }
624	        BigDecimal figure = figure(claim, grades, rates, floor);
625	        return figure != null ? figure.add(late.on(claim, figure)) : null;
626	    }
627	
628	    /** A claim's live due: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded
629	     *  half to even to two decimals, raised to the floor when below it; null (n/a) when no rate applies. */
630	    public static BigDecimal live(Claim claim, Grades grades, RateRepository rates, BigDecimal floor) {
631	        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date())
632	                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
633	                .map(due -> due.max(floor))
634	                .orElse(null);
635	    }
636	
637	    /** Whether a claim counts toward its person's figures and every live total: an OPEN or SETTLED one, except an
638	     *  OPEN one while its person is on hold. */
639	    public static boolean counts(Claim claim, boolean held) {
640	        return claim.status().counts() && !(held && claim.status() == ClaimStatus.OPEN);
641	    }
642	
643	    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
644	     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
645	     *  the grade in force on its date). */
646	    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, boolean held, LocalDate today,
647	            RateRepository rates, BigDecimal floor, LateCharge late) {
648	        List<Claim> counted = claims.stream().filter(c -> counts(c, held)).toList();
649	        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
650	                .filter(f -> f != null).toList();
651	        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
652	            return null;
653	        }
654	        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
655	    }
656	}
