659	import java.math.BigDecimal;
660	import java.math.RoundingMode;
661	import java.time.LocalDate;
662	import java.time.temporal.ChronoUnit;
663	import net.officefloor.hq.app.claim.Claim;
664	import net.officefloor.hq.app.claim.ClaimStatus;
665	import net.officefloor.hq.app.setting.SettingRepository;
666	import net.officefloor.hq.app.sheet.SheetRepository;
667	
668	/** The sheet's late charge as it is today: its terms (days; a claim's due-by is its date plus them), its late
669	 *  percent and its today (null: none, so nothing is overdue). */
670	public record LateCharge(int terms, BigDecimal pct, LocalDate today) {
671	
672	    /** The sheet's late charge as it is now. */
673	    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets) {
674	        return new LateCharge(settings.terms(sheetId), settings.latePct(sheetId), sheets.today(sheetId));
675	    }
676	
677	    /** No late charge at all. */
678	    public static LateCharge none() {
679	        return new LateCharge(0, BigDecimal.ZERO, null);
680	    }
681	
682	    /** Whether a claim is overdue: it is OPEN and its due-by is before today. */
683	    public boolean overdue(Claim claim) {
684	        return claim.status() == ClaimStatus.OPEN && today != null
685	                && claim.date().plusDays(terms).isBefore(today);
686	    }
687	
688	    /** The charge on a claim whose figure is `figure`: the late percent of the figure for every full 30 days it
689	     *  is overdue, rounded half to even to two decimals; 0.00 when it is not overdue. */
690	    public BigDecimal on(Claim claim, BigDecimal figure) {
691	        if (!overdue(claim) || pct.signum() == 0) {
692	            return new BigDecimal("0.00");
693	        }
694	        long periods = ChronoUnit.DAYS.between(claim.date().plusDays(terms), today) / 30;
695	        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
696	                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
697	    }
698	}
