package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: the amount is required, a
 *  number 0.00 or more with up to two decimals; the date, when given, is a real yyyy-mm-dd date. */
public class ValidateClaim {
    public void validate(@RequestBody ClaimRequest request, Out<ClaimInput> body) throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String amount = request.amount() == null ? "" : request.amount().trim();
        if (amount.isEmpty()) {
            throw new InvalidClaimException("An amount is required.");
        }
        if (!amount.matches("\\d{1,12}(\\.\\d{1,2})?")) {
            throw new InvalidClaimException("The amount must be a number, 0.00 or more, with up to two decimals.");
        }
        String rawDate = request.date() == null ? "" : request.date().trim();
        LocalDate date = null;
        if (!rawDate.isEmpty()) {
            if (!rawDate.matches("\\d{4}-\\d{2}-\\d{2}")) {
                throw new InvalidClaimException("The date must be a date (yyyy-mm-dd).");
            }
            try {
                date = LocalDate.parse(rawDate);
            } catch (DateTimeParseException e) {
                throw new InvalidClaimException("The date must be a real date (yyyy-mm-dd).");
            }
        }
        String note = request.note() == null ? "" : request.note().trim();
        if (note.length() > 1000) {
            throw new InvalidClaimException("A note is at most 1000 characters.");
        }
        body.set(new ClaimInput(request.user().trim(), new BigDecimal(amount).setScale(2), date, note));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read: a signed-in user and a known action. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusInput> body)
            throws InvalidClaimException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidClaimException("Sign in before changing claims.");
        }
        String action = request.action() == null ? "" : request.action().trim();
        ClaimStatus to = switch (action) {
            case "open" -> ClaimStatus.OPEN;
            case "settle" -> ClaimStatus.SETTLED;
            case "void" -> ClaimStatus.VOID;
            default -> throw new InvalidClaimException("Unknown claim action: " + action + ".");
        };
        body.set(new ClaimStatusInput(request.user().trim(), to));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.rate.RateRepository;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, else
     *  live: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded half to
     *  even to two decimals, and at least the sheet's floor; null (n/a) when no rate applies. */
    public static BigDecimal figure(Claim claim, Grades grades, RateRepository rates, BigDecimal floor) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.statedDue() != null) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, floor);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else its figure (bound or live) with
     *  the late charge on it added on top; null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, RateRepository rates, BigDecimal floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        BigDecimal figure = figure(claim, grades, rates, floor);
        return figure != null ? figure.add(late.on(claim, figure)) : null;
    }

    /** A claim's live due: its amount times its person's rate in force on its date for their grade then, divided by 100, rounded
     *  half to even to two decimals, raised to the floor when below it; null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, RateRepository rates, BigDecimal floor) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN))
                .map(due -> due.max(floor))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN or SETTLED one, except an
     *  OPEN one while its person is on hold. */
    public static boolean counts(Claim claim, boolean held) {
        return claim.status().counts() && !(held && claim.status() == ClaimStatus.OPEN);
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, boolean held, LocalDate today,
            RateRepository rates, BigDecimal floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, held)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The sheet's late charge as it is today: its terms (days; a claim's due-by is its date plus them), its late
 *  percent and its today (null: none, so nothing is overdue). */
public record LateCharge(int terms, BigDecimal pct, LocalDate today) {

    /** The sheet's late charge as it is now. */
    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets) {
        return new LateCharge(settings.terms(sheetId), settings.latePct(sheetId), sheets.today(sheetId));
    }

    /** No late charge at all. */
    public static LateCharge none() {
        return new LateCharge(0, BigDecimal.ZERO, null);
    }

    /** Whether a claim is overdue: it is OPEN and its due-by is before today. */
    public boolean overdue(Claim claim) {
        return claim.status() == ClaimStatus.OPEN && today != null
                && claim.date().plusDays(terms).isBefore(today);
    }

    /** The charge on a claim whose figure is `figure`: the late percent of the figure for every full 30 days it
     *  is overdue, rounded half to even to two decimals; 0.00 when it is not overdue. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        if (!overdue(claim) || pct.signum() == 0) {
            return new BigDecimal("0.00");
        }
        long periods = ChronoUnit.DAYS.between(claim.date().plusDays(terms), today) / 30;
        return figure.multiply(pct).multiply(BigDecimal.valueOf(periods))
                .divide(BigDecimal.valueOf(100), 2, RoundingMode.HALF_EVEN);
    }
}
